out.push("\n\n如果将 Modal 放在 storefront 内部，然后执行：\n\n```javascript\nstorefront.inert = true;\n```\n\n自定义 Modal 也会变得不可交互。\n\n### 12.2 基础 CSS\n\n```css\n#custom-modal[hidden] {\n  display: none !important;\n}\n\n#custom-modal {\n  position: fixed;\n  inset: 0;\n  z-index: 1000;\n\n  display: grid;\n  place-items: center;\n  padding: 16px;\n}\n\n.modal-overlay {\n  position: absolute;\n  inset: 0;\n  background: rgb(0 0 0 / 50%);\n}\n\n#modal-panel {\n  position: relative;\n\n  box-sizing: border-box;\n  width: min(100%, 600px);\n  max-height: 85dvh;\n  overflow: auto;\n\n  background: white;\n  color: #222;\n\n  padding: 24px;\n  border-radius: 12px;\n}\n```\n\n### 12.3 JavaScript 实现\n\n使用第 11 课介绍的 `focus-trap` 库，避免自行重新实现复杂的浏览器焦点计算。\n\n```bash\nnpm install focus-trap\n```\n\n```javascript\nimport { createFocusTrap } from 'focus-trap';\n\nconst storefront =\n  document.querySelector('#storefront');\n\nconst modal =\n  document.querySelector('#custom-modal');\n\nconst panel =\n  document.querySelector('#modal-panel');\n\nconst trigger =\n  document.querySelector('#open-modal');\n\nconst closeButton =\n  document.querySelector('#close-modal');\n\nlet trap;\nlet previousFocus;\nlet previousInert;\n\nfunction openModal(opener) {\n  if (!modal.hidden) return;\n\n  previousFocus = opener;\n  previousInert = storefront.inert;\n\n  modal.hidden = false;\n  storefront.inert = true;\n\n  lockScroll(modal);\n\n  trap = createFocusTrap(panel, {\n    initialFocus: '#modal-title',\n    fallbackFocus: panel,\n    escapeDeactivates: false,\n    returnFocusOnDeactivate: false,\n    clickOutsideDeactivates: false,\n    allowOutsideClick: event =>\n      event.target ===\n        modal.querySelector('.modal-overlay')\n  });\n\n  trap.activate();\n}\n\nfunction closeModal() {\n  if (modal.hidden) return;\n\n  trap?.deactivate();\n  trap = null;\n\n  modal.hidden = true;\n  storefront.inert = previousInert;\n\n  unlockScroll(modal);\n\n  if (previousFocus?.isConnected) {\n    previousFocus.focus();\n  }\n\n  previousFocus = null;\n}\n\ntrigger.addEventListener('click', event => {\n  openModal(event.currentTarget);\n});\n\ncloseButton.addEventListener('click', closeModal);\n\nmodal.querySelector('.modal-overlay')\n  .addEventListener('click', closeModal);\n\nmodal.addEventListener('keydown', event => {\n  if (\n    event.key === 'Escape' &&\n    !event.defaultPrevented\n  ) {\n    event.preventDefault();\n    closeModal();\n  }\n});\n```\n\n这里复用了前面的滚动锁定函数。代码中的 npm import 需要通过构建工具打包，不能直接将裸模块名称放进未配置模块解析的 Shopify JS 文件中。\n\n该实现针对单层、自定义模态弹窗。生产环境还需要处理备用焦点、嵌套弹窗栈、组件销毁和异常清理等情况。\n\n### 12.4 与原生 dialog 的对比\n\n| 能力 | 原生 dialog | 自定义 Modal |\n|---|---|---|\n| 基础 Role | 浏览器提供 | 手动添加 |\n| 模态背景隔离 | 浏览器提供 | 手动实现 |\n| Top Layer | 支持 | 通常不支持 |\n| 焦点限制 | 浏览器提供 | 手动实现或使用库 |\n| Esc 关闭 | 默认支持 | 手动实现 |\n| 焦点恢复 | 浏览器提供基础能力 | 手动实现 |\n| 遮罩 | `::backdrop` | 独立 DOM |\n| 多层弹窗 | 原生模态叠加能力 | 自己维护 |\n| 开发维护成本 | 相对较低 | 相对较高 |\n\n因此，如果没有特殊的浏览器兼容性或现有架构约束，新项目优先使用原生 dialog。\n\n---\n\n## 13. Popover API 与 Dialog 的区别\n\nPopover API 是另一项值得前端开发者掌握的原生 HTML 能力。\n\n例如网站中的配送说明浮层：\n\n```html\n<button\n  type=\"button\"\n  popovertarget=\"shipping-info\"\n>\n  Shipping information\n</button>\n\n<div id=\"shipping-info\" popover=\"auto\">\n  <p>Free shipping on orders over $50.</p>\n\n  <button\n    type=\"button\"\n    popovertarget=\"shipping-info\"\n    popovertargetaction=\"hide\"\n  >\n    Close\n  </button>\n</div>\n```\n\n上面的代码甚至不需要 JavaScript，就能够实现基础的显示与隐藏。\n\n");
