out.push("\n\n### 15.2 accessible-modal.js\n\n```javascript\nclass AccessibleModal extends HTMLElement {\n  connectedCallback() {\n    if (this.controller) return;\n\n    this.dialog = this.querySelector('dialog');\n\n    if (!this.dialog) return;\n\n    this.controller = new AbortController();\n\n    const signal = this.controller.signal;\n\n    this.dialog.addEventListener(\n      'close',\n      () => this.handleClose(),\n      { signal }\n    );\n\n    this.addEventListener('click', event => {\n      const button = event.target.closest(\n        '[data-modal-close]'\n      );\n\n      if (!button) return;\n\n      // 避免父层组件处理子层 Modal 的按钮\n      if (button.closest('accessible-modal') !== this) {\n        return;\n      }\n\n      this.requestClose();\n    }, { signal });\n  }\n\n  open(trigger = document.activeElement) {\n    if (!this.dialog || this.dialog.open) {\n      return;\n    }\n\n    this.opener = trigger;\n    this.openerId = trigger?.id;\n\n    this.dialog.returnValue = '';\n\n    this.dialog.showModal();\n  }\n\n  close(value = '') {\n    if (this.dialog?.open) {\n      this.dialog.close(value);\n    }\n  }\n\n  requestClose(value = '') {\n    if (!this.dialog?.open) return;\n\n    if (\n      typeof this.dialog.requestClose === 'function'\n    ) {\n      this.dialog.requestClose(value);\n      return;\n    }\n\n    // 旧浏览器的关闭前校验兼容方案\n    const event = new Event('cancel', {\n      cancelable: true\n    });\n\n    if (this.dialog.dispatchEvent(event)) {\n      this.dialog.close(value);\n    }\n  }\n\n  handleClose() {\n    // 避免旧 close 事件干扰已经重新打开的弹窗\n    if (this.dialog.open) return;\n\n    const active = document.activeElement;\n\n    // 原生浏览器已恢复合理焦点时，不主动抢夺\n    const needsRestoration =\n      !active ||\n      active === document.body ||\n      this.dialog.contains(active);\n\n    if (needsRestoration) {\n      this.restoreFocus();\n    }\n\n    this.opener = null;\n    this.openerId = null;\n\n    this.dispatchEvent(\n      new CustomEvent('modal:closed', {\n        bubbles: true,\n        detail: {\n          returnValue: this.dialog.returnValue\n        }\n      })\n    );\n  }\n\n  restoreFocus() {\n    const fallbackId =\n      this.getAttribute('data-fallback-focus');\n\n    const candidates = [\n      this.opener,\n\n      this.openerId\n        ? document.getElementById(this.openerId)\n        : null,\n\n      fallbackId\n        ? document.getElementById(fallbackId)\n        : null\n    ];\n\n    for (const element of candidates) {\n      if (!element?.isConnected) continue;\n      if (element.matches(':disabled')) continue;\n\n      if (\n        element.closest(\n          '[inert], [aria-hidden=\"true\"]'\n        )\n      ) {\n        continue;\n      }\n\n      element.focus();\n\n      if (document.activeElement === element) {\n        return;\n      }\n    }\n  }\n\n  disconnectedCallback() {\n    this.controller?.abort();\n    this.controller = null;\n\n    if (this.dialog?.open) {\n      this.dialog.close();\n    }\n\n    this.opener = null;\n    this.openerId = null;\n  }\n}\n\nif (!customElements.get('accessible-modal')) {\n  customElements.define(\n    'accessible-modal',\n    AccessibleModal\n  );\n}\n```\n\n这里主要实现了：\n\n| 能力 | 实现方式 |\n|---|---|\n| 原生模态行为 | `showModal()` |\n| 关闭前校验 | `requestClose()` |\n| 旧浏览器兼容 | 特性检测与 cancel 事件 |\n| 焦点恢复 | 原触发元素及备用 ID |\n| 生命周期管理 | connected/disconnectedCallback |\n| 事件清理 | AbortController |\n| 业务事件 | `modal:closed` |\n\n### 15.3 通用触发机制\n\n为了支持动态渲染的 Shopify 商品卡片，可以采用事件委托。\n\n```javascript\ndocument.addEventListener('click', event => {\n  const trigger = event.target.closest(\n    '[data-modal-open]'\n  );\n\n  if (!trigger) return;\n\n  const modal = document.getElementById(\n    trigger.dataset.modalOpen\n  );\n\n  if (!(modal instanceof AccessibleModal)) {\n    return;\n  }\n\n  event.preventDefault();\n\n  modal.open(trigger);\n});\n```\n\n这样即使 Shopify Section Rendering 替换了触发按钮，新按钮也能够继续工作。\n\n### 15.4 在 Liquid 中使用\n\n例如创建 `snippets/size-guide-modal.liquid`：\n\n```liquid\n{%- assign modal_id = 'SizeGuide-' \n  | append: section.id\n-%}\n\n<button\n  type=\"button\"\n  id=\"Open-{{ modal_id }}\"\n  data-modal-open=\"{{ modal_id }}\"\n  aria-haspopup=\"dialog\"\n>\n  Size guide\n</button>\n\n<accessible-modal\n  id=\"{{ modal_id }}\"\n  data-fallback-focus=\"MainContent\"\n>\n\n  <dialog\n    aria-labelledby=\"Title-{{ modal_id }}\"\n    class=\"size-guide-modal\"\n  >\n\n    <h2\n      id=\"Title-{{ modal_id }}\"\n      tabindex=\"-1\"\n      autofocus\n    >\n      Size guide\n    </h2>\n\n    <button\n      type=\"button\"\n      data-modal-close\n      aria-label=\"Close size guide\"\n    >\n      ×\n    </button>\n\n    <div class=\"modal-content\">\n      {{ content }}\n    </div>\n\n  </dialog>\n\n</accessible-modal>\n```\n\n这里的 content 是调用 snippet 时传入的内容参数。\n\n这个示例假设每个 Section 只渲染一个 Size Guide。若存在多个实例，需要额外传入唯一实例标识，避免 ID 冲突。\n\n### 15.5 在 theme.liquid 中加载\n\n```liquid\n<script\n  src=\"{{ 'accessible-modal.js' | asset_url }}\"\n  defer=\"defer\"\n></script>\n```\n\n配合前面的 dialog CSS、Drawer CSS 和滚动锁定样式，就能够在多个业务组件中复用同一套基础设施。\n\n### 15.6 组件设计的边界\n\n不建议把所有购物车、商品、库存、搜索等业务逻辑都塞进 AccessibleModal。\n\n比较合理的分层是：\n\n| 模块 | 职责 |\n|---|---|\n| AccessibleModal | 弹窗生命周期、语义、焦点 |\n| CartDrawer | 商品数量、删除、购物车 API |\n| ProductForm | 商品加购 |\n| AccessibilityAnnouncer | 动态消息通知 |\n| ScrollLockManager | 滚动锁定 |\n| SectionRenderer | HTML 更新、焦点保留 |\n\n上面的 Web Component 是基础教学版本。它假设 dialog 外壳保持稳定、脚本在 HTML 解析后执行；对于动态替换整个 dialog、复杂嵌套弹窗、快速重开及异步卸载等场景，还需要进一步完善和测试。\n\n---\n\n## 16. 如何测试弹窗组件？\n\n### 16.1 检查真正的模态状态\n\n在 DevTools Console 中执行：\n\n```javascript\nconst dialog = document.querySelector('dialog');\n\nconsole.table({\n  open: dialog.open,\n\n  modal: dialog.matches(':modal'),\n\n  activeElement: document.activeElement,\n\n  focusInside:\n    dialog.contains(document.activeElement)\n});\n```\n\n一个值得记住的选择器：\n\n```javascript\ndocument.querySelectorAll('dialog:modal');\n```\n\n它可以找到当前处于原生模态状态的 dialog。\n\n而：\n\n```javascript\ndocument.querySelectorAll('dialog[open]');\n```\n\n还可能包含非模态对话框。\n\n### 16.2 Playwright 自动化测试\n\n```javascript\nimport { test, expect } from '@playwright/test';\n\ntest('size guide modal accessibility', async ({ page }) => {\n  await page.goto('/products/cotton-tshirt');\n\n  const trigger = page.getByRole('button', {\n    name: 'Size guide',\n    exact: true\n  });\n\n  await trigger.focus();\n  await page.keyboard.press('Enter');\n\n  const dialog = page.getByRole('dialog', {\n    name: 'Size guide'\n  });\n\n  await expect(dialog).toBeVisible();\n\n  await expect(\n    dialog.getByRole('heading', {\n      name: 'Size guide'\n    })\n  ).toBeFocused();\n\n  await page.keyboard.press('Escape');\n\n  await expect(dialog).not.toBeVisible();\n\n  await expect(trigger).toBeFocused();\n});\n```\n\n这可以验证几个核心行为：\n\n- 键盘能够打开弹窗。\n- 弹窗具有正确的 Role 和 Name。\n- 初始焦点正确。\n- Esc 能够关闭。\n- 关闭后恢复焦点。\n\n但这还不是完整的无障碍测试，需要补充 Tab 正向与反向导航、背景隔离、不同屏幕尺寸以及真实屏幕阅读器测试。\n\n---\n\n## 17. 本课知识测试\n\n");
